"""Source-bound approach geometry for NRS 484B.400(2)(a).

Distances describe observed body position; no distance is a legal cutoff.
"""
import argparse
import hashlib
import json
import math
from pathlib import Path


def _finite_pair(value, label):
    if not isinstance(value, list) or len(value) != 2 or any(
            type(v) not in (int, float) or not math.isfinite(v) for v in value):
        raise ValueError('missing finite ' + label)
    return value


def _unit(a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    norm = math.hypot(dx, dy)
    if norm < 1:
        raise ValueError('degenerate approach centerline')
    return dx / norm, dy / norm


def validate_context(context):
    """Require two opposed lanes on each intersecting road, with a left-turn route."""
    if context.get('law_id') != 'NRS-484B-400-2a' or context.get('cell_id') != 'C109705':
        raise ValueError('wrong frozen law/cell')
    if context.get('maneuver') != 'left_turn' or context.get('control') != 'centerline':
        raise ValueError('wrong fixed maneuver/control')
    if context.get('public_highway_source') is None:
        raise ValueError('public-highway source missing')
    roads = context.get('intersecting_roads')
    if not isinstance(roads, list) or len(roads) != 2:
        raise ValueError('both intersecting highways required')
    lane_directions = {}
    for road in roads:
        if not road.get('road_id') or road.get('alley') is not False:
            raise ValueError('road identity or non-alley source missing')
        lanes = road.get('lanes')
        if not isinstance(lanes, list) or len(lanes) < 2:
            raise ValueError('two-directional lane inventory missing')
        directions = []
        for lane in lanes:
            directions.append(_unit(_finite_pair(lane.get('from_xy_m'), 'lane start'),
                                    _finite_pair(lane.get('to_xy_m'), 'lane end')))
        lane_directions[road['road_id']] = directions
        if not any(a[0] * b[0] + a[1] * b[1] < -.95
                   for a in directions for b in directions):
            raise ValueError('opposing permitted directions missing')
    if context.get('approach_road_id') == context.get('departure_road_id'):
        raise ValueError('left turn must enter intersecting road')
    ids = {road['road_id'] for road in roads}
    if {context.get('approach_road_id'), context.get('departure_road_id')} != ids:
        raise ValueError('approach/departure road mismatch')
    line = context.get('approach_centerline_xy_m')
    if not isinstance(line, list) or len(line) != 2:
        raise ValueError('approach centerline source missing')
    a, b = (_finite_pair(point, 'centerline point') for point in line)
    direction = _unit(a, b)
    if type(context.get('approach_half_width_m')) not in (int, float) or context['approach_half_width_m'] <= 2:
        raise ValueError('approach right-half edge missing')
    if context.get('centerline_kind') not in ('marked', 'imaginary_equidistant'):
        raise ValueError('marked or imaginary centerline source missing')
    approach_road = next(road for road in roads if road['road_id'] == context['approach_road_id'])
    aligned = False
    for lane, lane_direction in zip(approach_road['lanes'], lane_directions[approach_road['road_id']]):
        if lane_direction[0] * direction[0] + lane_direction[1] * direction[1] < .95:
            continue
        start = lane['from_xy_m']
        lateral = direction[1] * (start[0] - a[0]) - direction[0] * (start[1] - a[1])
        if 0 < lateral < context['approach_half_width_m']:
            aligned = True
    if not aligned:
        raise ValueError('approach lane does not align with centerline right half')
    return a, direction


def body_position(context, vertices):
    """Right-normal signed body offsets from an oriented approach centerline."""
    a, direction = validate_context(context)
    if not isinstance(vertices, list) or len(vertices) < 4:
        raise ValueError('original full-body footprint missing')
    offsets = []
    for vertex in vertices:
        x, y = _finite_pair(vertex, 'body vertex')
        offsets.append(direction[1] * (x - a[0]) - direction[0] * (y - a[1]))
    half = context['approach_half_width_m']
    return {'nearest_body_edge_to_centerline_m': min(offsets),
            'farthest_body_edge_from_centerline_m': max(offsets),
            'all_body_in_right_half': min(offsets) >= 0 and max(offsets) <= half}


def _verified(attempt, name, acquisition):
    path = attempt / name
    declared = acquisition.get(name, {})
    if (path.is_symlink() or path.resolve().parent != attempt.resolve() or
            not path.is_file() or declared.get('kind') != 'original_native'):
        raise ValueError('missing original Native source: ' + name)
    actual = hashlib.sha256(path.read_bytes()).hexdigest()
    if actual != declared.get('sha256'):
        raise ValueError('stale original Native source: ' + name)
    return path, actual


def measure(attempt):
    attempt = Path(attempt)
    acquisition = json.loads((attempt / 'acquisition.json').read_text())
    context_path, context_hash = _verified(attempt, 'intersection-context.json', acquisition)
    history_path, history_hash = _verified(attempt, 'approach-history.jsonl', acquisition)
    frames_path, frames_hash = _verified(attempt, 'video_frames.jsonl', acquisition)
    context = json.loads(context_path.read_text())
    validate_context(context)
    rows = [json.loads(line) for line in history_path.read_text().splitlines() if line.strip()]
    frame_rows = [json.loads(line) for line in frames_path.read_text().splitlines() if line.strip()]
    if len(rows) < 2:
        raise ValueError('original approach history too short')
    if len(frame_rows) != len(rows):
        raise ValueError('original four-camera frame map length mismatch')
    previous = None
    approach = []
    departure = []
    views = {'overview', 'approach', 'reference_corner', 'driver_reference'}
    identity_keys = {'video_frame', 'carla_frame', 'native_frame'}
    for index, (row, video) in enumerate(zip(rows, frame_rows)):
        frame, time_s = row.get('frame'), row.get('time_s')
        if type(frame) is not int or type(time_s) not in (int, float) or not math.isfinite(time_s):
            raise ValueError('invalid original frame/time')
        if previous is not None and (frame != previous[0] + 1 or abs(time_s - previous[1] - .05) > .005):
            raise ValueError('missing or non-20-Hz original approach frame')
        previous = (frame, time_s)
        video_time = video.get('time_s')
        if video.get('frame') != frame or type(video_time) not in (int, float) or not math.isfinite(video_time) or abs(video_time - time_s) > .005:
            raise ValueError('original four-camera frame identity mismatch')
        if identity_keys & video.keys() and (
                set(video) & identity_keys != identity_keys or
                type(video.get('video_frame')) is not int or
                video['video_frame'] != index or
                any(type(video.get(key)) is not int or video[key] != frame
                    for key in ('carla_frame', 'native_frame'))):
            raise ValueError('canonical original frame identity mismatch')
        camera_frames = video.get('camera_frames')
        if not isinstance(camera_frames, dict) or set(camera_frames) != views or any(
                type(camera_frames[name]) is not int or camera_frames[name] != frame
                for name in views):
            raise ValueError('original four-camera synchronized frames missing')
        camera_times = video.get('camera_times_s')
        if camera_times is not None and (
                not isinstance(camera_times, dict) or set(camera_times) != views or
                any(type(camera_times[name]) not in (int, float) or
                    not math.isfinite(camera_times[name]) or
                    abs(camera_times[name] - time_s) > .001 for name in views)):
            raise ValueError('original four-camera timestamp drift')
        yaw = row.get('ego_heading_rad')
        if type(yaw) not in (int, float) or not math.isfinite(yaw):
            raise ValueError('original ego heading missing')
        if row.get('road_id') == context['approach_road_id'] and row.get('phase') == 'approach':
            position = body_position(context, row.get('ego_body_vertices_xy_m'))
            approach.append({'frame': frame, 'time_s': time_s, 'ego_heading_rad': yaw,
                             **position})
        elif row.get('road_id') == context['departure_road_id'] and row.get('phase') == 'departure':
            departure.append({'frame': frame, 'ego_heading_rad': yaw})
    if len(approach) < 2:
        raise ValueError('pre-entry approach body samples missing')
    if len(departure) < 2 or departure[0]['frame'] <= approach[-1]['frame']:
        raise ValueError('observed departure after approach missing')
    yaw_change = (departure[-1]['ego_heading_rad'] - approach[-1]['ego_heading_rad'] + math.pi) % (2 * math.pi) - math.pi
    if not .3 < yaw_change < 2.8:
        raise ValueError('observed left-turn heading change missing')
    return {'format': 'worker-400-2a-approach-measurement',
            'approach_frames': [row['frame'] for row in approach],
            'departure_frames': [row['frame'] for row in departure],
            'observed_left_turn_heading_change_rad': yaw_change,
            'nearest_body_edge_range_m': [min(row['nearest_body_edge_to_centerline_m'] for row in approach),
                                          max(row['nearest_body_edge_to_centerline_m'] for row in approach)],
            'all_sampled_body_in_right_half': all(row['all_body_in_right_half'] for row in approach),
            'body_history': approach,
            'centerline_kind': context['centerline_kind'],
            'source_sha256': {'intersection-context.json': context_hash,
                              'approach-history.jsonl': history_hash,
                              'video_frames.jsonl': frames_hash},
            'legal_nearest_portion_verdict': 'unresolved'}


def compare(left, right):
    """Reject changed fixed context and report only measured lateral difference."""
    a, b = (json.loads(Path(path).read_text()) for path in (left, right))
    fixed = ('law_id', 'cell_id', 'maneuver', 'control', 'public_highway_source',
             'intersecting_roads', 'approach_road_id', 'departure_road_id',
             'approach_centerline_xy_m', 'approach_half_width_m', 'centerline_kind',
             'camera_plan', 'duration_s', 'controller_policy')
    validate_context(a['context']); validate_context(b['context'])
    for key in fixed:
        if a['context'].get(key) != b['context'].get(key):
            raise ValueError('comparison fixed condition changed: ' + key)
    x, y = a['measurement'], b['measurement']
    if x['source_sha256'] == y['source_sha256']:
        raise ValueError('comparison reuses same original sources')
    return {'near_min_m': x['nearest_body_edge_range_m'][0],
            'far_min_m': y['nearest_body_edge_range_m'][0],
            'signed_difference_m': y['nearest_body_edge_range_m'][0] - x['nearest_body_edge_range_m'][0],
            'legal_verdict': 'unresolved'}


def compare_original_attempts(near_attempt, far_attempt):
    """Recompute both sides from sealed Native sources before comparing them."""
    prefix = 'testing__C109705__NRS-484B-400-2a__motor_vehicle_driver__'
    paths = [Path(near_attempt), Path(far_attempt)]
    acquisitions = [json.loads((p / 'acquisition.json').read_text()) for p in paths]
    case_ids = [a.get('case_id') for a in acquisitions]
    allowed = ((prefix + 'near_centerline', prefix + 'farther_from_centerline'),
               (prefix + 'imaginary_near_centerline', prefix + 'imaginary_farther_from_centerline'))
    if tuple(case_ids) not in allowed:
        raise ValueError('wrong exact approach comparison case pair')
    contexts = [json.loads(_verified(path, 'intersection-context.json', acquisition)[0].read_text())
                for path, acquisition in zip(paths, acquisitions)]
    measurements = [measure(path) for path in paths]
    for case_id, context in zip(case_ids, contexts):
        expected = 'imaginary_equidistant' if '__imaginary_' in case_id else 'marked'
        if context['centerline_kind'] != expected:
            raise ValueError('case/centerline source mismatch')
    left = {'context': contexts[0], 'measurement': measurements[0]}
    right = {'context': contexts[1], 'measurement': measurements[1]}
    fixed = ('law_id', 'cell_id', 'maneuver', 'control', 'public_highway_source',
             'intersecting_roads', 'approach_road_id', 'departure_road_id',
             'approach_centerline_xy_m', 'approach_half_width_m', 'centerline_kind',
             'camera_plan', 'duration_s', 'controller_policy')
    for key in fixed:
        if left['context'].get(key) != right['context'].get(key):
            raise ValueError('comparison fixed condition changed: ' + key)
    if measurements[0]['source_sha256'] == measurements[1]['source_sha256']:
        raise ValueError('comparison reuses same original sources')
    if not all(m['all_sampled_body_in_right_half'] for m in measurements):
        raise ValueError('comparison approach body leaves sourced right half')
    near = measurements[0]['nearest_body_edge_range_m'][0]
    far = measurements[1]['nearest_body_edge_range_m'][0]
    if not far > near:
        raise ValueError('measured farther approach is not farther')
    return {'format': 'worker-400-2a-source-bound-comparison',
            'case_ids': case_ids, 'source_sha256': [m['source_sha256'] for m in measurements],
            'near_min_m': near, 'far_min_m': far,
            'signed_difference_m': far - near, 'legal_verdict': 'unresolved'}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--output', required=True)
    args = parser.parse_args()
    Path(args.output).write_text(json.dumps(measure(args.attempt), indent=2) + '\n')


if __name__ == '__main__':
    main()

"""Source-bound CARLA actor and camera owner for one surveyed left turn.

The packet supplies numerical spawn, route and four camera poses. This module
does not infer a public-highway status from a CARLA map name or image.
"""
from __future__ import annotations

import io
import math
import threading
from copy import deepcopy
from pathlib import Path

from PIL import Image

from construction import control
from saved_delivery import CAMERAS


def _number(value):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError('finite numerical CARLA source required')
    return float(value)


def _pose(carla, value):
    if not isinstance(value, dict):
        raise ValueError('surveyed CARLA pose missing')
    return carla.Transform(
        carla.Location(x=_number(value['x']), y=_number(value['y']),
                       z=_number(value['z'])),
        carla.Rotation(pitch=_number(value.get('pitch', 0)),
                       yaw=_number(value['yaw']), roll=_number(value.get('roll', 0))))


class NativeCarlaAdapter:
    """Own a synchronous world session, ego actor and exact four camera sensors."""

    native_attested = True

    def __init__(self, world, carla, packet, config, client=None):
        self.world, self.carla = world, carla
        self.client = client
        self.packet, self.config = packet, config
        self.ego_actor = None
        self.sensors = {}
        self.original_settings = None
        self.route = []
        self.route_index = 0
        self.target_speed_mps = None
        self.frames = {name: {} for name in CAMERAS}
        self.condition = threading.Condition()
        self.callback_error = None
        self.current = None
        self.recorder_path = None

    def start_recorder(self, path):
        """Start the CARLA server recorder after actors have been acquired."""
        if self.client is None or self.ego_actor is None or self.recorder_path is not None:
            raise ValueError('Native recorder requires a live owned actor and client')
        path = Path(path)
        if path.exists():
            raise ValueError('Native recorder path already exists')
        result = self.client.start_recorder(str(path), True)
        if result is False:
            raise ValueError('Native recorder refused to start')
        self.recorder_path = path

    def stop_recorder(self):
        if self.recorder_path is None:
            raise ValueError('Native recorder was not started')
        path = self.recorder_path
        self.client.stop_recorder()
        if not path.is_file() or not path.stat().st_size:
            raise ValueError('Native recorder source missing after stop')
        info = self.client.show_recorder_file_info(str(path), False)
        if not isinstance(info, str) or 'Create ' not in info:
            raise ValueError('Native recorder actor census missing')
        return info

    def start(self, plan):
        if plan['map_name'] != self.world.get_map().name:
            raise ValueError('Native map identity differs from reviewed plan')
        spawn = self.packet.get('spawn_transform')
        if not isinstance(spawn, dict) or any(
                abs(_number(spawn[key]) - plan['spawn_xy_m'][index]) > .1
                for index, key in enumerate(('x', 'y'))):
            raise ValueError('surveyed Native spawn differs from exact construction')
        route = self.packet.get('route_transforms')
        if (not isinstance(route, list) or len(route) < 2 or
                [row.get('waypoint_id') for row in route] !=
                plan['left_turn_route_waypoint_ids']):
            raise ValueError('surveyed Native route differs from exact construction')
        camera_poses = self.packet.get('camera_transforms')
        if not isinstance(camera_poses, dict) or set(camera_poses) != set(CAMERAS):
            raise ValueError('four surveyed Native camera poses required')
        dimensions = {row['name']: (row['width'], row['height'])
                      for row in self.config['cameras']}
        if set(dimensions) != set(CAMERAS):
            raise ValueError('four exact camera dimensions required')
        self.route = [(_number(row['x']), _number(row['y'])) for row in route]
        self.target_speed_mps = _number(plan['controller_policy']['target_speed_mps'])
        if self.target_speed_mps <= 0:
            raise ValueError('Native controller speed must be positive')
        self.original_settings = deepcopy(self.world.get_settings())
        settings = self.world.get_settings()
        settings.synchronous_mode = True
        settings.fixed_delta_seconds = .05
        self.world.apply_settings(settings)
        try:
            library = self.world.get_blueprint_library()
            ego_bp = library.find(plan['ego_blueprint_id'])
            self.ego_actor = self.world.try_spawn_actor(ego_bp, _pose(self.carla, spawn))
            if self.ego_actor is None:
                raise ValueError('Native ego spawn failed')
            for name in sorted(CAMERAS):
                width, height = dimensions[name]
                bp = library.find('sensor.camera.rgb')
                bp.set_attribute('image_size_x', str(width))
                bp.set_attribute('image_size_y', str(height))
                bp.set_attribute('sensor_tick', '0.05')
                sensor = self.world.try_spawn_actor(
                    bp, _pose(self.carla, camera_poses[name]))
                if sensor is None:
                    raise ValueError('Native camera spawn failed: ' + name)
                self.sensors[name] = sensor
                sensor.listen(self._callback(name, width, height))
        except BaseException:
            self.cleanup()
            raise

    def _callback(self, name, width, height):
        def receive(image):
            try:
                if (image.width, image.height) != (width, height):
                    raise ValueError('Native camera dimensions differ: ' + name)
                raw = bytes(image.raw_data)
                if len(raw) != width * height * 4:
                    raise ValueError('Native camera BGRA byte count differs: ' + name)
                picture = Image.frombytes('RGBA', (width, height), raw,
                                          'raw', 'BGRA').convert('RGB')
                stream = io.BytesIO()
                picture.save(stream, format='PNG')
                with self.condition:
                    if image.frame in self.frames[name]:
                        raise ValueError('duplicate Native camera frame: ' + name)
                    self.frames[name][image.frame] = {
                        'frame': image.frame, 'time_s': image.timestamp,
                        'png': stream.getvalue()}
                    self.condition.notify_all()
            except BaseException as error:
                with self.condition:
                    self.callback_error = error
                    self.condition.notify_all()
        return receive

    def tick(self):
        if self.ego_actor is None:
            raise ValueError('Native ego actor is not owned')
        transform = self.ego_actor.get_transform()
        location = transform.location
        velocity = self.ego_actor.get_velocity()
        speed = math.sqrt(velocity.x ** 2 + velocity.y ** 2 + velocity.z ** 2)
        while (self.route_index + 1 < len(self.route) and
               math.hypot(location.x - self.route[self.route_index][0],
                          location.y - self.route[self.route_index][1]) < 1):
            self.route_index += 1
        command = control((location.x, location.y), math.radians(transform.rotation.yaw),
                          self.route[self.route_index], speed,
                          target_speed_mps=self.target_speed_mps)
        self.ego_actor.apply_control(self.carla.VehicleControl(**command))
        frame = self.world.tick()
        snapshot = self.world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError('Native world tick and snapshot differ')
        self.current = {'frame': frame, 'time_s': snapshot.timestamp.elapsed_seconds}
        return dict(self.current)

    def _body(self, frame):
        if self.current is None or self.current['frame'] != frame:
            raise ValueError('Native ego readback frame differs')
        transform = self.ego_actor.get_transform()
        vertices = self.ego_actor.bounding_box.get_world_vertices(transform)
        if len(vertices) < 4:
            raise ValueError('Native full body vertices missing')
        body = [[_number(v.x), _number(v.y), _number(v.z)] for v in vertices]
        waypoint = self.world.get_map().get_waypoint(transform.location)
        if waypoint is None:
            raise ValueError('Native ego road identity missing')
        return body, waypoint.road_id, transform

    def read_ego(self, frame):
        body, road_id, transform = self._body(frame)
        context = self.packet['context']
        phase = ('approach' if road_id == context['approach_road_id'] else
                 'departure' if road_id == context['departure_road_id'] else
                 'connector')
        return {'frame': frame, 'case_id': self.config['selected_case_id'],
                'phase': phase, 'road_id': road_id,
                'ego_heading_rad': math.radians(transform.rotation.yaw),
                'ego_body_vertices_xy_m': [v[:2] for v in body]}

    def read_body(self, frame):
        body, road_id, _ = self._body(frame)
        velocity = self.ego_actor.get_velocity()
        return {'frame': frame, 'road_id': road_id, 'body_vertices_m': body,
                'velocity_mps': [_number(velocity.x), _number(velocity.y),
                                 _number(velocity.z)],
                'velocity_source': 'original_trace_actor_get_velocity'}

    def read_participants(self, frame):
        """Retain same-tick source bodies and motion for every live road user."""
        if self.current is None or self.current['frame'] != frame:
            raise ValueError('Native participant readback frame differs')
        actors = sorted((actor for actor in self.world.get_actors()
                         if getattr(actor, 'is_alive', False) and
                         isinstance(getattr(actor, 'type_id', None), str) and
                         actor.type_id.startswith(('vehicle.', 'walker.'))),
                        key=lambda actor: actor.id)
        if sum(actor.id == self.ego_actor.id for actor in actors) != 1:
            raise ValueError('Native participant stream missing subject')
        if len({actor.id for actor in actors}) != len(actors):
            raise ValueError('Native participant IDs duplicated')
        result = []
        for actor in actors:
            transform = actor.get_transform()
            velocity = actor.get_velocity()
            vector = [_number(velocity.x), _number(velocity.y),
                      _number(velocity.z)]
            vertices = actor.bounding_box.get_world_vertices(transform)
            if len(vertices) < 4:
                raise ValueError('Native participant full body missing')
            result.append({'actor_id': actor.id, 'blueprint': actor.type_id,
                           'velocity_mps': vector,
                           'speed_mps': math.sqrt(sum(value * value for value in vector)),
                           'heading_deg': _number(transform.rotation.yaw),
                           'body_vertices_m': [[_number(vertex.x), _number(vertex.y),
                                               _number(vertex.z)] for vertex in vertices]})
        return result

    def read_control_inventory(self, frame):
        """Snapshot every live traffic actor from the current Native world tick."""
        if self.current is None or self.current['frame'] != frame:
            raise ValueError('Native control inventory frame differs')
        actors = sorted((actor for actor in self.world.get_actors()
                         if getattr(actor, 'is_alive', False) and
                         isinstance(getattr(actor, 'type_id', None), str) and
                         actor.type_id.startswith('traffic.')),
                        key=lambda actor: actor.id)
        ids = [actor.id for actor in actors]
        if any(type(value) is not int or value < 0 for value in ids) or len(set(ids)) != len(ids):
            raise ValueError('Native traffic actor IDs invalid')
        devices = []
        for actor in actors:
            location = actor.get_transform().location
            device = {'actor_id': actor.id, 'blueprint': actor.type_id,
                      'position_m': [_number(location.x), _number(location.y),
                                     _number(location.z)]}
            if actor.type_id == 'traffic.traffic_light':
                boxes = actor.get_light_boxes()
                if not boxes:
                    raise ValueError('Native signal group source missing')
                device['light_box_method'] = 'TrafficLight.get_light_boxes'
                device['light_boxes'] = [
                    {'light_box_index': index} for index, _ in enumerate(boxes)]
                device['state'] = str(actor.get_state()).split('.')[-1]
            devices.append(device)
        return {'frame': frame, 'time_s': self.current['time_s'],
                'devices': devices,
                'control_actor_inventory': {
                    'frame': frame, 'time_s': self.current['time_s'],
                    'method': 'World.get_actors', 'prefix': 'traffic.',
                    'actor_ids': ids, 'complete': True}}

    def read_cameras(self, frame):
        with self.condition:
            if not self.condition.wait_for(lambda: self.callback_error is not None or
                                           all(frame in self.frames[name] for name in CAMERAS),
                                           timeout=5):
                raise ValueError('Native four-camera callbacks timed out')
            if self.callback_error is not None:
                raise ValueError('Native camera callback failed') from self.callback_error
            return {name: self.frames[name].pop(frame) for name in CAMERAS}

    def read_road_geometry(self):
        geometry = self.packet.get('road_geometry')
        if not isinstance(geometry, dict):
            raise ValueError('surveyed Native road geometry missing')
        return geometry

    def brake(self):
        if self.ego_actor is not None:
            self.ego_actor.apply_control(self.carla.VehicleControl(throttle=0,
                                                                   brake=1, steer=0))

    def cleanup(self):
        errors = []
        for sensor in reversed(list(self.sensors.values())):
            try:
                sensor.stop()
                sensor.destroy()
            except BaseException as error:
                errors.append(error)
        self.sensors.clear()
        if self.ego_actor is not None:
            try:
                self.ego_actor.destroy()
            except BaseException as error:
                errors.append(error)
            self.ego_actor = None
        if self.original_settings is not None:
            try:
                self.world.apply_settings(self.original_settings)
                restored = self.world.get_settings()
                if (restored.synchronous_mode != self.original_settings.synchronous_mode or
                        restored.fixed_delta_seconds != self.original_settings.fixed_delta_seconds):
                    raise ValueError('Native CARLA world settings restoration differs')
            except BaseException as error:
                errors.append(error)
            self.original_settings = None
        if errors:
            raise RuntimeError('Native CARLA owner cleanup failed') from errors[0]
